class Solution {
public:
    string reverseWords(string s) {
        int n = s.size();
        int i = 0;
        while (i < n) {
            int start = i;
            while (i < n && s[i] != ' ') i++;
            int end = i - 1;
            while (start < end) {
                char tmp = s[start];
                s[start] = s[end];
                s[end] = tmp;
                start++;
                end--;
            }
            i++;
        }
        return s;
    }
};
